"%% mc_03 : Monte Carlo robustness screening -- closed-loop short-period spec
% Elevator state feedback u = -K x on the nominal 4-state longitudinal model
% x = [u, w, q, theta].  Short-period poles placed at wn = 2.3 rad/s,
% zeta = 0.58; phugoid poles held at their open-loop values.
% Monte Carlo over N = 200 deterministic samples: +/-30% uniform multipliers
% on Mw, Zw, Mq drawn with independent seeds.

clear; clc; close all;

%% ---- Nominal longitudinal model (ft/s, ft/s, rad/s, rad) ----
V   = 690.0;
Xu  = -0.007;   Xw = 0.045;
Zu  = -0.04;    Zw = -0.8;
Mw  = -0.0062;  Mq = -1.05;
g   = 32.174;

A = [ Xu    Xw    0    -g ;
      Zu    Zw    V     0 ;
      0     Mw    Mq    0 ;
      0     0     1     0 ];

B = [0; -6.5; -5.0; 0];                       % elevator input effectiveness

% sanity: model must be controllable for pole placement
assert(rank(ctrb(A,B)) == 4, 'Nominal (A,B) not controllable');

%% ---- State-feedback design: SP at wn=2.3, zeta=0.58, phugoid at open-loop ----
wn_sp   = 2.3;
zeta_sp = 0.58;

wd_sp  = wn_sp*sqrt(1 - zeta_sp^2);
sp_des = -zeta_sp*wn_sp + 1i*wd_sp;           % desired short-period pair

ol     = eig(A);                              % open-loop poles
[~, o] = sort(abs(ol), 'descend');
ph_ol  = ol(o(3:4));                          % slow pair = phugoid (kept)

pdes = [ph_ol(1); ph_ol(2); sp_des; conj(sp_des)];
K    = place(A, B, pdes);                     % u = -K x  =>  eig(A - B*K)

% verify nominal closed-loop short-period meets the design targets
lam0 = eig(A - B*K);
[~, s0] = sort(abs(lam0), 'descend');
sp0  = lam0(s0(1:2));
wn0  = abs(sp0);
zt0  = -real(sp0)./wn0;
fprintf('Nominal closed-loop SP: wn = %.4f rad/s, zeta = %.4f\n', wn0(1), zt0(1));

%% ---- Monte Carlo: N = 200 deterministic samples, +/-30% uniform box ----
N   = 200;
pct = 0.30;

rng(20260829); f_Mw = 1 + pct*(2*rand(N,1) - 1);   % Mw multipliers
rng(20261829); f_Zw = 1 + pct*(2*rand(N,1) - 1);   % Zw multipliers
rng(20262829); f_Mq = 1 + pct*(2*rand(N,1) - 1);   % Mq multipliers

count = 0;
wn_hist = zeros(N,1);
zt_hist = zeros(N,1);

for i = 1:N
    Ai = [ Xu    Xw          0           -g ;
           Zu    f_Zw(i)*Zw  V            0 ;
           0     f_Mw(i)*Mw  f_Mq(i)*Mq   0 ;
           0     0           1            0 ];

    lam = eig(Ai - B*K);                     % closed-loop poles, sample i
    [~, o] = sort(abs(lam), 'descend');
    sp  = lam(o(1:2));                       % short-period = fastest (largest |s|) pair

    wn_i = abs(sp);
    zt_i = -real(sp)./wn_i;

    wn_hist(i) = wn_i(1);
    zt_hist(i) = zt_i(1);

    % pass: SP omega_n in [2.2, 2.4] rad/s AND zeta >= 0.55 (both poles of pair)
    if all(wn_i >= 2.2 & wn_i <= 2.4) && all(zt_i >= 0.55)
        count = count + 1;
    end
end

pass_fraction      = count/N;
failing_case_count = N - count;

fprintf('MC screening (N = %d): pass = %d, fail = %d, pass_fraction = %.4f\n', ...
        N, count, failing_case_count, pass_fraction);

%% ---- Write result.json ----
result = struct('pass_fraction',      pass_fraction, ...
                'failing_case_count', failing_case_count);

fid = fopen('result.json', 'w');
if fid == -1
    error('Unable to open result.json for writing.');
end
fwrite(fid, jsonencode(result), 'char');
fclose(fid);
disp('result.json written.');"
